"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[104],{87619(e){e.exports=JSON.parse('{"tag":{"label":"dynamic-programming","permalink":"/azeon/p-vs-np/tags/dynamic-programming","allTagsPath":"/azeon/p-vs-np/tags","count":3,"items":[{"id":"heuristics/dynamic-programming-limits","title":"Dynamic Programming Limits","description":"Dynamic programming solves knapsack exactly with a simple table. It looks polynomial. It isn\'t, and watching the table grow one digit at a time shows exactly why pseudo-polynomial time breaks down for big numbers.","permalink":"/azeon/p-vs-np/heuristics/dynamic-programming-limits"},{"id":"heuristics/ptas-and-fptas","title":"PTAS and FPTAS","description":"For some NP-Hard problems you get to choose: name any accuracy you like, say within 1% of the best, and there\'s a polynomial-time algorithm that achieves it. The price is time. Knapsack is the classic example, and it uses a rounding trick I love.","permalink":"/azeon/p-vs-np/heuristics/ptas-and-fptas"},{"id":"np-completeness/the-knapsack-problem","title":"The Knapsack Problem","description":"A bag with a weight limit and a pile of things worth different amounts. The obvious strategy fails, the clever strategy is secretly exponential, and an entire encryption scheme was once built on top of it and broken.","permalink":"/azeon/p-vs-np/np-completeness/the-knapsack-problem"}],"unlisted":false}}')}}]);